(async () => {
  const list = await window.etn.layers.list('{{networkId}}');
  const current = list.find((l) => l.current === true) ?? null;
  return current === null ? null : current.id;
})()

(() => { const parseCss = (value) => {
    const raw = String(value).trim().toLowerCase();
    if (raw.startsWith('#')) {
      const hex = raw.length === 4 ? raw.slice(1).split('').map((c) => c + c).join('') : raw.slice(1);
      return { rgb: [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16)), alpha: 1 };
    }
    const cs = /^color\(srgb\s+([\d.]+)\s+([\d.]+)\s+([\d.]+)(?:\s*\/\s*([\d.]+%?))?\)$/.exec(raw);
    if (cs !== null) {
      const a = cs[4] === undefined ? 1 : (cs[4].endsWith('%') ? Number.parseFloat(cs[4]) / 100 : Number(cs[4]));
      return { rgb: [Number(cs[1]), Number(cs[2]), Number(cs[3])].map((c) => c * 255), alpha: a };
    }
    const m = /rgba?\(([^)]+)\)/.exec(raw);
    if (m === null) return null;
    const parts = m[1].split(',').map((part) => Number(part));
    return { rgb: parts.slice(0, 3), alpha: parts.length === 4 ? parts[3] : 1 };
  };
  const lum = (rgb) => {
    const lin = (c) => { const v = c / 255; return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; };
    return 0.2126 * lin(rgb[0]) + 0.7152 * lin(rgb[1]) + 0.0722 * lin(rgb[2]);
  };
  const ratio = (a, b) => { const x = lum(a); const y = lum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
  const SHARE = 0.78;
  const expectedText = (surfaceRgb, bgRgb, wallpaperOn) => {
    const under = wallpaperOn ? surfaceRgb : surfaceRgb.map((c, i) => SHARE * c + (1 - SHARE) * bgRgb[i]);
    return lum(under) > 0.35 ? '#1f242d' : '#ffffff';
  };
  const root = getComputedStyle(document.documentElement);
  const surface = parseCss(root.getPropertyValue('--surface').trim());
  const layerBgText = root.getPropertyValue('--layer-bg').trim();
  const themeBgText = root.getPropertyValue('--bg').trim();
  const bg = parseCss(layerBgText !== '' ? layerBgText : themeBgText);
  const wallpaper = document.documentElement.getAttribute('data-canvas-wallpaper') === 'on';
  const counters = [...document.querySelectorAll('.zone-count')].filter((el) => !el.classList.contains('hidden'));
  const expected = surface === null || bg === null ? null : expectedText(surface.rgb, bg.rgb, wallpaper);
  const facts = counters.map((el) => {
    const st = getComputedStyle(el);
    const plate = parseCss(st.backgroundColor);
    const fg = parseCss(st.color);
    const composed = plate === null || bg === null ? null : plate.rgb.map((c, i) => plate.alpha * c + (1 - plate.alpha) * bg.rgb[i]);
    return {
      color: String(getComputedStyle(el).color || '').toLowerCase(),
      plate_alpha: plate === null ? 0 : Number(plate.alpha.toFixed(2)),
      contrast: composed === null || fg === null ? 0 : Number(ratio(fg.rgb, composed).toFixed(2)),
    };
  });
  return {
    wallpaper_off: wallpaper === false,
    layer_bg: layerBgText.toLowerCase(),
    layer_bg_own: layerBgText !== '' && layerBgText !== themeBgText,
    expected_text: expected,
    counter_present: counters.length > 0,
    all_expected_text: expected !== null && facts.length > 0 && facts.every((f) => { const actual = parseCss(f.color); const want = parseCss(expected); return actual !== null && want !== null && actual.rgb.every((v, i) => Math.abs(v - want.rgb[i]) < 1); }),
    all_plate_share: facts.length > 0 && facts.every((f) => Math.abs(f.plate_alpha - SHARE) < 0.02),
    min_contrast: facts.length === 0 ? 0 : Math.min(...facts.map((f) => f.contrast)),
    contrast_ok: facts.length > 0 && facts.every((f) => f.contrast >= 7),
  };
})()

